const fs = require('fs');
const readline = require('readline');

const fileStream = fs.createReadStream('C:\\\\Users\\\\vishn\\\\.gemini\\\\antigravity\\\\brain\\\\3a5bc55d-cb17-47e2-9f44-9aa86a60a457\\\\.system_generated\\\\logs\\\\transcript.jsonl');
const rl = readline.createInterface({ input: fileStream, crlfDelay: Infinity });

let promptIdx = 1;
const prompts = [];

rl.on('line', (line) => {
  if (!line.trim()) return;
  try {
    const obj = JSON.parse(line);
    if (obj.type === 'USER_INPUT') {
      let content = obj.content || '';
      // Strip system wrappers like <USER_REQUEST>, <ADDITIONAL_METADATA>, <USER_SETTINGS_CHANGE>
      const match = content.match(/<USER_REQUEST>([\s\S]*?)<\/USER_REQUEST>/);
      const cleanContent = match ? match[1].trim() : content.trim();
      prompts.push({
        index: promptIdx++,
        step: obj.step_index,
        timestamp: obj.created_at,
        prompt: cleanContent
      });
    }
  } catch (e) {}
});

rl.on('close', () => {
  console.log(JSON.stringify(prompts, null, 2));
});
